/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
req={p.stem for p in Path('/workspace/requirements').glob('*.yaml')}
patch={p.stem for p in Path('/workspace/requirement_patches').glob('*.diff')}
for name in sorted(req-patch):
