/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
patches={p.stem for p in Path('/workspace/requirement_patches').glob('*.diff')}
for path in sorted(Path('/workspace/requirements').glob('*.yaml')):
    if path.stem in patches:
        continue
    title=''
    for line in path.read_text().splitlines():
        if line.startswith('title:'):
            title=line[len('title:'):].strip()
            break
    print(f'{path.stem}\\t{title}')
PY"

/bin/bash -lc "python3 - <<'PY'
